def diagnose(train, val, patience=8, gap_ratio=1.5):
    n = len(val)
    best_epoch = int(min(range(n), key=lambda e: val[e]))
    best_val = val[best_epoch]
    wait, stop_epoch = 0, n - 1
    for e in range(best_epoch + 1, n):
        if val[e] < best_val - 1e-4:
            best_val, wait = val[e], 0
        else:
            wait += 1
            if wait >= patience:
                stop_epoch = e
                break
    overfit = False
    cnt = 0
    for e in range(best_epoch + 1, n):
        if train[e] > 0 and val[e] / train[e] > gap_ratio:
            cnt += 1
            if cnt >= 5:
                overfit = True
        else:
            cnt = 0
    return {"best_epoch": best_epoch, "stop_epoch": stop_epoch,
            "overfit": overfit, "best_val": best_val,
            "final_gap_ratio": val[-1] / train[-1]}

